/* Rentcam CMS v6 — global status/delete manager */
(function(){
 if(!location.pathname.startsWith('/cms'))return;
 let current='mainCategories',custom=false;
 const publishing=()=>window.RentcamCmsPublishing;
 const cfg=()=>publishing().get();
 const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
 const defs=[['mainCategories','Main Category'],['subCategories','Sub Category'],['brands','Brand'],['banners','Banner'],['portfolio','Portfolio'],['articles','Artikel'],['services','Layanan'],['navigation','Menu'],['footer','Footer']];
 function arr(k){return publishing().collection(k)}
 function save(){return publishing().save().catch(e=>console.error('Gagal menyimpan status CMS',e))}
 function style(){if(document.getElementById('v6globalstyle'))return;const s=document.createElement('style');s.id='v6globalstyle';s.textContent=`.v6-global-nav{height:44px!important;border:0!important;background:transparent!important;color:#aeb2b9!important;border-radius:9px!important;padding:0 14px!important;text-align:left!important;font-weight:800!important;font-size:14px!important;cursor:pointer!important}.v6-global-nav.on,.v6-global-nav:hover{background:#25282e!important;color:#fff!important}.v6g-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.v6g-tab{height:40px;border:1px solid #dfe1e5;border-radius:9px;background:#fff;padding:0 13px;font-size:13px;font-weight:800;cursor:pointer}.v6g-tab.on{background:#17181a;color:#fff}.v6g-table{width:100%;border-collapse:collapse;min-width:720px}.v6g-table th{background:#fafafa;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#73777e;text-align:left;padding:13px}.v6g-table td{font-size:14px;padding:13px;border-top:1px solid #eceef0}.v6g-actions{display:flex;gap:7px;flex-wrap:wrap}.v6g-btn{height:38px;border:1px solid #dfe1e5;border-radius:9px;background:#fff;padding:0 12px;font-weight:800;font-size:12px;cursor:pointer}.v6g-btn.warn{background:#fff8df;color:#8a6500}.v6g-btn.danger{background:#fff2f2;color:#b52e2e;border-color:#ffd5d5}`;document.head.appendChild(s)}
 function addNav(){const n=document.querySelector('.v5-nav');if(!n||n.querySelector('.v6-global-nav'))return;const b=document.createElement('button');b.className='v6-global-nav';b.textContent='Status & Hapus Data';b.onclick=()=>{custom=true;document.querySelectorAll('.v5-nav button').forEach(x=>x.classList.remove('on'));b.classList.add('on');render()};n.appendChild(b)}
 function state(x,k){const a=arr(k),i=a.indexOf(x);return i>=0?publishing().isCollectionActive(k,i):false}
 function render(){const root=document.querySelector('.v5-content');if(!root)return;const a=arr(current);root.innerHTML=`<div class="v5-card"><div class="v5-head"><div><h2>Status & Hapus Data</h2><p>Semua master data dan konten bisa dinonaktifkan tanpa dihapus, atau dihapus dari CMS.</p></div><button class="v5-btn" data-v6g-back>← Kembali</button></div><div class="v6g-tabs">${defs.map(d=>`<button class="v6g-tab ${d[0]===current?'on':''}" data-v6g-tab="${d[0]}">${d[1]}</button>`).join('')}</div><div class="v5-tablewrap"><table class="v6g-table"><thead><tr><th>Nama</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${a.map((x,i)=>`<tr><td><b>${esc(x.name||x.title||x.label||x.id||('Data '+(i+1)))}</b></td><td>${state(x,current)?'<span class="v5-pill on">Aktif</span>':'<span class="v5-pill">Nonaktif</span>'}</td><td><div class="v6g-actions"><button class="v6g-btn warn" data-v6g-toggle="${i}">${state(x,current)?'Nonaktifkan':'Aktifkan'}</button><button class="v6g-btn danger" data-v6g-delete="${i}">Hapus</button></div></td></tr>`).join('')||'<tr><td colspan="3">Belum ada data.</td></tr>'}</tbody></table></div></div>`}
 document.addEventListener('click',e=>{if(e.target.closest('.v5-nav button:not(.v6-global-nav)'))custom=false;const t=e.target.closest('[data-v6g-tab]');if(t){current=t.dataset.v6gTab;render();return}if(e.target.closest('[data-v6g-back]')){custom=false;location.reload();return}const g=e.target.closest('[data-v6g-toggle]');if(g){if(publishing().toggleCollection(current,+g.dataset.v6gToggle)){save();setTimeout(render,100)}return}const d=e.target.closest('[data-v6g-delete]');if(d){publishing().deleteCollection(current,+d.dataset.v6gDelete);save();setTimeout(render,100)}});
 const mo=new MutationObserver(()=>{style();addNav()});mo.observe(document.documentElement,{childList:true,subtree:true});style();setTimeout(addNav,500);
})();